 85	export const exMulti = {
 86	  /* Địa chỉ máy chủ: ?multi= nếu có; ?test không có multi= thì rỗng (không mở mạng); còn lại cấu hình */
 87	  url(): string {
 88	    const q = new URLSearchParams(location.search);
 89	    const u = q.get('multi');
 90	    if (u !== null) return u;
 91	    return q.has('test') ? '' : M.url;
 92	  },
 93	  get session(): MultiSession | null { return session; },
 94	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
 95	
 96	  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
 97	  begin(onReady: () => void): boolean {
 98	    const url = exMulti.url();
 99	    if (!url || session) return false;
100	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
101	    let ready = false;
102	    s.onPos = f => exRemotes.onPos(f, performance.now());
103	    s.onChange = () => {
104	      exRemotes.sync(s.flyers, s.mySlot);
105	      if (s.phase === 'solo') exLabelsClear();
106	      renderRoster();
107	      if (s.phase === 'flying') idleStart(); else idleStop();
108	      exMulti.onChange();
109	      if (!ready) { ready = true; onReady(); }
110	    };
111	    s.open();
112	    return true;
113	  },
114	
115	  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
116	  update(_dt: number, nowMs: number, state: GliderState | null): void {
117	    if (!session) return;
118	    exRemotes.update(nowMs);
119	    exLabelsUpdate(camera, exRemotes, nowMs);
120	    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
121	      sentAt = nowMs;
122	      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
123	      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank));
124	    }
125	  },
126	
127	  /* Người bay vừa bấm phím điều khiển: đếm lại thời gian rời máy */
128	  activity(): void {
129	    if (!idle) return;
130	    idle.activity(performance.now());
131	    idleShow('');
132	  },
133	
134	  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
135	  watchState(): GliderState | null {
136	    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
137	  }
138	};
139	
140	onLang(() => { rosterKey = ''; renderRoster(); });
141	/* ===== Dù lượn nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
142	   Hiện sau khi bấm thẻ Dù lượn lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người đang bay, ô tên, nút Bay ngay.
143	   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
144	   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến + nút Bay một mình.
145	   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm). */
146	import { CONFIG } from '../../config';
147	import { t, onChange as onLang } from '../../i18n';
148	import { exMulti } from './index';
149	import { exSanitizeName } from './protocol';
150	import type { MultiSession } from './session';
151	
152	export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void }
153	
154	const M = CONFIG.explore.multi;
155	const NAME_KEY = 'exMpName';
156	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
157	
158	export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
159	export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }
160	
161	let listKey = '';
162	let langBound = false;
163	let redraw: (() => void) | null = null;
164	
165	/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
166	export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
167	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
168	  const input = $<HTMLInputElement>('exMpNameIn'), fly = $<HTMLButtonElement>('exMpFly'), solo = $<HTMLButtonElement>('exMpSolo');
169	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
170	  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
171	  box.setAttribute('aria-labelledby', 'exMpSky');
172	  root.hidden = false;
173	  if (!input.value) input.value = loadName();
174	  listKey = '';
175	  let done = false;
176	  const finish = (f: () => void) => { if (done) return; done = true; exMulti.onChange = () => {}; redraw = null; f(); };
177	
178	  const render = () => {
179	    if (done) return;
180	    const ph = session.phase;
181	    if (ph === 'flying') { finish(cb.onFly); return; }
182	    if (ph === 'watching') { finish(cb.onWatch); return; }
183	    const offline = ph === 'solo';
184	    $('exMpOnline').hidden = offline;
185	    $('exMpOffline').hidden = !offline;
186	    solo.hidden = !offline;
187	    if (offline) { if (document.activeElement !== solo) solo.focus({ preventScroll: true }); return; }
188	    const ready = ph === 'lobby';
189	    const free = M.slots - session.flyers.length;
190	    $('exMpSeats').textContent = ready ? t('exMpSeats', { n: free }) : '…';
191	    $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
192	    const taken = new Set(session.flyers.map(f => f.slot));
193	    $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
194	      d.classList.toggle('on', taken.has(i));
195	      d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
196	    });
197	    const key = session.flyers.map(f => f.slot + ':' + f.name).join('|');
198	    if (key !== listKey) {
199	      listKey = key;
200	      const list = $('exMpList'); list.textContent = '';
201	      for (const f of session.flyers) {
202	        const row = document.createElement('div'); row.className = 'ex-mp-row';
203	        const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
204	        const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
205	        row.append(dot, nm); list.appendChild(row);
206	      }
207	    }
208	    $('exMpNameBad').hidden = session.notice !== 'nameBad';
209	    fly.disabled = !ready || exSanitizeName(input.value) === null;
210	  };
211	
212	  const go = () => {
213	    const name = exSanitizeName(input.value);
214	    if (name === null || session.phase !== 'lobby') return;
215	    saveName(name);
216	    session.join(name);
217	  };
218	  input.addEventListener('input', () => {
219	    $('exMpNameBad').hidden = true;
220	    const ok = exSanitizeName(input.value);
221	    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
222	    fly.disabled = session.phase !== 'lobby' || ok === null;
223	  });
224	  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
225	  fly.addEventListener('click', go);
226	  solo.addEventListener('click', () => finish(cb.onSolo), { once: true });
227	
228	  redraw = render;
229	  if (!langBound) { langBound = true; onLang(() => { if (redraw) redraw(); }); }
230	  exMulti.onChange = render;
231	  render();
232	  input.focus({ preventScroll: true });
233	}
  1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
  2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
  3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
  4	
  5	import { getLang, onChange } from '../i18n';
  6	import { exMulti } from './multi';
  7	import { exShowLobby } from './multi/lobby';
  8	
  9	export type ExChoice = 'glider' | 'guided';
 10	
 11	const el = () => document.getElementById('chooser');
 12	
 13	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
 14	function lockGliderOnTouch(root: HTMLElement): void {
 15	  if (!window.matchMedia('(hover: none)').matches) return;
 16	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
 17	  if (!card) return;
 18	  card.disabled = true;
 19	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
 20	}
 21	
 22	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
 23	function wireLang(root: HTMLElement): void {
 24	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
 25	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
 26	  if (!mine || !main) return;
 27	  mine.innerHTML = main.innerHTML; mine.value = getLang();
 28	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
 29	  onChange((code) => { mine.value = code; });
 30	}
 31	
 32	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
 33	const inerted: HTMLElement[] = [];
 34	function setUnderInert(root: HTMLElement, on: boolean): void {
 35	  if (on) {
 36	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
 37	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
 38	      c.inert = true; inerted.push(c);
 39	    }
 40	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
 41	}
 42	
 43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: () => void = () => {}): void {
 44	  const root = el();
 45	  if (!root) return;
 46	  lockGliderOnTouch(root);
 47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLost */
 48	  try { if (sessionStorage.getItem('exMpNotice') === 'lost') { sessionStorage.removeItem('exMpNotice'); const n = document.getElementById('exMpLostNote'); if (n) n.hidden = false; } } catch { /* bộ nhớ bị chặn */ }
 49	  wireLang(root);
 50	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
 51	    if (b.disabled) return;
 52	    b.addEventListener('click', () => {
 53	      const choice = b.dataset.pick as ExChoice;
 54	      /* Dù lượn có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay một mình ngay như trước */
 55	      if (choice === 'glider' && exMulti.begin(() => {})) {
 56	        const solo = () => { exHideChooser(); onPick('glider'); };
 57	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(); }, onSolo: solo });
 58	        return;
 59	      }
 60	      exHideChooser(); onPick(choice);
 61	    }, { once: true });
 62	  });
 63	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
 64	  const loading = document.getElementById('loading');
 65	  if (!loading || loading.classList.contains('done')) { show(); return; }
 66	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
 67	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
 68	}
 69	
 70	export function exHideChooser(): void {
 71	  const root = el();
 72	  if (root) { root.hidden = true; setUnderInert(root, false); }
 73	}

