  1	/* ===== Dù lượn nhiều người: dù của người bay cùng =====
  2	   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
  3	   Vị trí nhận 5 lần/s được nội suy, lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
  4	   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
  5	import * as THREE from 'three';
  6	import { scene } from '../../core/renderer';
  7	import { CONFIG } from '../../config';
  8	import { exBuildGlider, exPlaceGlider } from '../glider';
  9	import type { GliderState } from '../flight';
 10	import { ExTrack, type ExPose } from './interp';
 11	import type { Flyer } from './protocol';
 12	
 13	const M = CONFIG.explore.multi;
 14	
 15	interface RemoteSlot {
 16	  name: string | null;        // null = slot trống
 17	  group: THREE.Group | null;
 18	  track: ExTrack;
 19	  pose: ExPose;               // đệm lấy mẫu
 20	  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
 21	  live: boolean;              // đã có mẫu và đang hiện
 22	}
 23	
 24	const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
 25	  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
 26	  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
 27	}));
 28	let me = -1;
 29	
 30	function hide(s: RemoteSlot): void {
 31	  s.track.reset(); s.live = false;
 32	  if (s.group) s.group.visible = false;
 33	}
 34	
 35	export const exRemotes = {
 36	  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
 37	  sync(flyers: Flyer[], mySlot: number): void {
 38	    me = mySlot;
 39	    for (let i = 0; i < slots.length; i++) {
 40	      const s = slots[i];
 41	      let name: string | null = null;
 42	      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
 43	      if (name === null) { s.name = null; hide(s); continue; }
 44	      if (name !== s.name) {
 45	        s.name = name; hide(s);
 46	        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ vào phản chiếu nước, giữ draw call ≈ 1 mỗi dù
 47	      }
 48	    }
 49	  },
 50	
 51	  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank]; chỉ nhận slot đã biết chủ và không phải của mình */
 52	  onPos(f: number[][], nowMs: number): void {
 53	    for (const e of f) {
 54	      const i = e[0], s = slots[i];
 55	      if (!s || i === me || s.name === null) continue;
 56	      s.track.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
 57	    }
 58	  },
 59	
 60	  update(nowMs: number): void {
 61	    const t = nowMs - M.interpSends * 1000 / M.sendHz;
 62	    for (const s of slots) {
 63	      if (s.name === null || !s.group) continue;
 64	      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
 65	      const p = s.pose;
 66	      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
 67	      exPlaceGlider(s.group, s.state);
 68	      s.group.visible = s.live = true;
 69	    }
 70	  },
 71	
 72	  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
 73	  slotState(slot: number): GliderState | null {
 74	    const s = slots[slot];
 75	    return s && s.live ? s.state : null;
 76	  },
 77	
 78	  /* Dù và tên của slot (cho nhãn tên và test); null nếu slot trống */
 79	  group(slot: number): THREE.Group | null { const s = slots[slot]; return s && s.name !== null ? s.group : null; },
 80	  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },
 81	
 82	  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
 83	  clear(): void {
 84	    me = -1;
 85	    for (const s of slots) { s.name = null; hide(s); }
 86	  }
 87	};
 88	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
 89	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018). */
 90	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
 91	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
 92	
 93	export class ExTrack {
 94	  private buf = new Float64Array(N * W);
 95	  private head = 0;      // chỉ số ô sẽ ghi tiếp
 96	  private n = 0;         // số mẫu đang có
 97	  get count(): number { return this.n; }
 98	
 99	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
100	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
101	    const o = this.head * W, b = this.buf;
102	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
103	    this.head = (this.head + 1) % N;
104	    if (this.n < N) this.n++;
105	  }
106	
107	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
108	  sample(t: number, out: ExPose): boolean {
109	    if (this.n === 0) return false;
110	    const b = this.buf, first = (this.head + N - this.n) % N * W;
111	    const last = ((this.head + N - 1) % N) * W;
112	    let a = first, c = first;
113	    if (t >= b[last]) a = c = last;
114	    else if (t > b[first]) {
115	      for (let i = 0; i < this.n - 1; i++) {
116	        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
117	        if (t <= b[q]) { a = p; c = q; break; }
118	      }
119	    }
120	    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
121	    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
122	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
123	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
124	    let dy = b[c + 4] - b[a + 4];
125	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
126	    out.yaw = b[a + 4] + dy * k;
127	    out.bank = b[a + 5] + (b[c + 5] - b[a + 5]) * k;
128	    return true;
129	  }
130	
131	  reset(): void { this.n = 0; this.head = 0; }
132	}
133	/* ===== Dù lượn nhiều người: máy trạng thái phiên (không DOM, không three) ===== */
134	import type { Flyer, ServerMsg } from './protocol';
135	import type { Transport } from './client';
136	import { multiParams } from './params';
137	
138	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
139	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
140	
141	export class MultiSession {
142	  phase: Phase = 'connecting';
143	  flyers: Flyer[] = [];
144	  mySlot = -1;
145	  watched = -1;       // slot đang xem, -1 = không ai
146	  invite = false;     // đang xem và còn chỗ trống
147	  notice: Notice = '';
148	  name = '';
149	  onChange: () => void = () => {};
150	  onPos: (f: number[][]) => void = () => {};
151	  private t: Transport | null = null;
152	  private disposed = false;
153	  private first = true; // chưa nhận lobby nào
154	
155	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n)) {}
156	
157	  open(): void {
158	    this.connect().then(t => {
159	      if (this.disposed) { t.close(); return; }
160	      this.t = t;
161	      t.onMessage = m => this.recv(m);
162	      t.onClose = () => this.lost();
163	    }, () => {
164	      if (this.disposed) return;
165	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
166	    });
