174	  // Rời chỗ bay (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
175	  leave(): void {
176	    if (this.phase !== 'flying') return;
177	    this.t?.send({ t: 'leave' });
178	    this.notice = 'released'; this.toWatching();
179	    this.onChange();
180	  }
