202	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
203	  private fixWatched(): void {
204	    const ids = this.flyers.map(f => f.slot);
205	    if (this.phase === 'watching') {
206	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
