253	/* ===== Dù lượn nhiều người: kết nối WebSocket tới máy chủ ===== */
254	import type { ClientMsg, ServerMsg } from './protocol';
255	
256	export interface Transport {
257	  send(m: ClientMsg): void;
258	  close(): void;
259	  onMessage: (m: ServerMsg) => void;
260	  onClose: () => void;
261	}
262	
263	// Mở WebSocket; reject khi lỗi hoặc quá hạn timeoutMs
264	export function exConnect(url: string, timeoutMs: number): Promise<Transport> {
265	  return new Promise<Transport>((resolve, reject) => {
266	    let ws: WebSocket;
267	    try { ws = new WebSocket(url); } catch (e) { reject(e); return; }
268	    let opened = false;
269	    let handler: ((m: ServerMsg) => void) | null = null;
270	    const pending: ServerMsg[] = [];   // tin tới trước khi người dùng gán onMessage (máy chủ gửi lobby ngay khi nhận kết nối) được giữ lại, không mất
271	    const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
272	    const t: Transport = {
273	      send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
274	      close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
275	      get onMessage() { return handler as (m: ServerMsg) => void; },
276	      set onMessage(fn: (m: ServerMsg) => void) { handler = fn; while (pending.length) fn(pending.shift() as ServerMsg); },
277	      onClose: () => {}
278	    };
279	    ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
280	    ws.onmessage = ev => {
281	      let m: ServerMsg;
282	      try { m = JSON.parse(String(ev.data)); } catch (e) { return; }
283	      if (m && typeof m.t === 'string') { if (handler) handler(m); else pending.push(m); }
284	    };
285	    ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
286	    ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
287	  });
288	}

