  6	
  7	export type Out = { to: string | 'all'; msg: ServerMsg };
  8	
  9	interface Slot { id: string; name: string; seen: number; pos: number[] | null }
 10	interface Conn { stamps: number[] }
 11	
 12	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
 13	
 14	export class SkyRoom {
 15	  private conns = new Map<string, Conn>();
 16	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
 17	  private lastBroadcast = -Infinity;
 18	
 19	  private lobby(): Out {
 20	    const flyers: Flyer[] = [];
 21	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
 22	    return { to: 'all', msg: { t: 'lobby', flyers } };
 23	  }
 24	
 25	  connect(id: string, now: number): Out[] | null {
 26	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
 27	    this.conns.set(id, { stamps: [] });
 28	    return [{ to: id, msg: this.lobby().msg }];
 29	  }
 30	
