162	    const a = ws.deserializeAttachment() as Att | null;
163	    if (!a || typeof data !== 'string') return;
164	    this.dispatch(this.room.message(a.id, data, Date.now()));
165	    await this.armAlarm();
166	  }
167	
168	  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
169	  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }
170	
171	  async alarm(): Promise<void> {
172	    this.dispatch(this.room.sweep(Date.now()));
173	    await this.armAlarm();
174	  }
175	
176	  private drop(ws: WebSocket): void {
177	    const a = ws.deserializeAttachment() as Att | null;
178	    if (a) this.dispatch(this.room.disconnect(a.id));
179	  }
180	
181	  // Gửi tin ra socket rồi ghi lại slot/tên mới vào attachment (để sống sót qua hibernation)
182	  private dispatch(outs: Out[]): void {
183	    const socks = this.state.getWebSockets();
184	    for (const o of outs) {
185	      const text = JSON.stringify(o.msg);
186	      for (const ws of socks) {
187	        const a = ws.deserializeAttachment() as Att | null;
188	        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
189	        try { ws.send(text); } catch { /* socket đã đóng */ }
190	      }
191	      if (o.msg.t === 'lobby') this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
192	    }
193	    for (const ws of socks) {
194	      const a = ws.deserializeAttachment() as Att | null;
195	      if (!a) continue;
196	      const slot = this.room.slotOf(a.id);
197	      const name = slot >= 0 ? (this.names.get(slot) ?? a.name) : '';
198	      if (slot !== a.slot || name !== a.name) ws.serializeAttachment({ id: a.id, slot, name } as Att);
199	    }
200	  }
201	
202	  private async armAlarm(): Promise<void> {
203	    if (!this.room.hasFlyers()) return;
204	    if ((await this.state.storage.getAlarm()) === null) await this.state.storage.setAlarm(Date.now() + P.sweepMs);
205	  }
206	}
207	/* ===== Lọc tên tục (ngắn gọn, vi + en) ===== */
208	const BAD = ['dit', 'du ma', 'dm', 'dcm', 'dmm', 'cac', 'lon', 'buoi', 'dkm', 'vcl', 'vl', 'cutt', 'dam', 'fuck', 'shit', 'bitch', 'cunt', 'dick', 'pussy', 'asshole', 'nigger', 'nigga', 'fag', 'rape', 'sex'];
209	
210	// Hạ chữ thường, bỏ dấu (đ → d), bỏ ký tự ngăn cách rồi tìm từ cấm
211	export function exIsBad(name: string): boolean {
212	  const flat = name.toLowerCase().replace(/đ/g, 'd').normalize('NFD').replace(/\p{M}/gu, '');
213	  const spaced = flat.replace(/[^a-z0-9]+/g, ' ').trim();
214	  const tight = spaced.replace(/ /g, '');
215	  const words = spaced.split(' ');
216	  return BAD.some(b => (b.length <= 3 ? words.includes(b) || tight === b : tight.includes(b.replace(/ /g, ''))));
217	}
218	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
219	import { multiParams } from './params';
220	
221	export type ClientMsg =
222	  | { t: 'join'; name: string }
223	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number }
224	  | { t: 'hb' }
225	  | { t: 'leave' };
226	
227	export interface Flyer { slot: number; name: string }
228	
229	// f: mỗi phần tử [slot, x, y, z, yaw, bank]
230	export type ServerMsg =
231	  | { t: 'lobby'; flyers: Flyer[] }
232	  | { t: 'joined'; slot: number }
233	  | { t: 'rejected'; why: 'full' | 'name' }
234	  | { t: 'pos'; f: number[][] }
235	  | { t: 'released' };
236	
237	// Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng; rỗng hoặc quá nameMax grapheme → null
238	export function exSanitizeName(raw: string): string | null {
239	  if (typeof raw !== 'string') return null;
240	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '‍' ? c : '')).trim();
241	  if (!s) return null;
242	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
243	  let n = 0;
244	  for (const _ of seg.segment(s)) if (++n > multiParams.nameMax) return null;
245	  return s;
246	}
