254	  posMaxPerSec: 8,       // gói pos tối đa một kết nối được gửi trong 1 s, quá thì bỏ (ước lượng)
255	  heartbeatMs: 3000,     // ms giữa hai nhịp sống khi không đổi vị trí (ước lượng)
