258	  connectTimeoutMs: 4000, // ms chờ kết nối WebSocket trước khi coi là lỗi (ước lượng)
259	  idleMs: 60000,         // ms không chạm phím thì hiện hỏi "Bạn còn đó không?" (ước lượng)
260	  idleWarnMs: 15000,     // ms đếm ngược sau khi hỏi, hết thì trả slot (ước lượng)
261	  idleTickMs: 500,       // ms giữa hai lần kiểm tra rời máy (setInterval, không dùng rAF để tab ẩn vẫn đếm) (ước lượng)
