417	   417	  bots.forEach((b) => b.close());
418	   418	  try { await browser?.close(); } catch { /* bỏ qua */ }
419	   419	  try { srv?.close(); } catch { /* bỏ qua */ }
420	   420	  stop();
421	   421	  await sleep(1500);
422	   422	}
423	   423	console.log(problems.length ? `multi-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'multi-check: đạt');
424	   424	process.exit(problems.length ? 1 : 0);
