  1	// Kiểm tra dù lượn nhiều người ở phía khách (kế hoạch feature/du-luon-nhieu-nguoi, Task 5).
  2	//   Mục 1: 4 bot Node WebSocket bay cùng — dù, màu, nhãn tên, nhãn dưới cánh, draw call (≤ +4), roster, bot thoát.
  3	//   Mục 2: ?test không có multi= thì không mở WebSocket nào.
  4	//   Mục 3 (Task 6): bước chọn slot + nhập tên trong màn chọn — số chỗ trực tiếp, tên, chống chèn HTML/RTL, nhớ tên, máy chủ tắt, đổi ngôn ngữ.
  5	//   Mục 4 (Task 7): chế độ xem (5 bot), lời mời vào chỗ trống, giành trước, người xem rời, ô tên không lái dù, Esc, mất máy chủ khi xem và khi bay.
  6	//   Mục 5 (Task 8): rời máy — đếm ngược, trả slot, camera giữ nguyên, lời mời còn dùng, phím giữ slot, nhịp sống không nhân đôi, đóng trang, tab ẩn + rAF dừng.
  7	//   Tự spawn `wrangler dev` ở cổng 8799 và luôn kill khi xong hoặc lỗi.
  8	//
  9	//   npm run build && npm run test:multi
 10	import { fileURLToPath } from 'node:url';
 11	import { spawn } from 'node:child_process';
 12	import { serveDir, launch, openApp, frames } from './lib.mjs';
 13	
 14	const PORT = 8799, HOST = `127.0.0.1:${PORT}`;
 15	const problems = [];
 16	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
 17	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
 18	
 19	const wr = spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['wrangler', 'dev', '--port', String(PORT)], { cwd: fileURLToPath(new URL('../server/multi/', import.meta.url)), shell: process.platform === 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
 20	let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
 21	const stop = () => { try { if (process.platform === 'win32') spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); else wr.kill(); } catch { /* bỏ qua */ } };
 22	process.on('exit', stop);
 23	
 24	// Dù chính đứng yên ở BASE, hướng +X; bot bay tại chỗ phía trước, hơi lệch hai bên
 25	const BASE = { x: 500, y: 150, z: 100 };
 26	function bot(name, ox, oz) {
 27	  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
 28	  const b = { ws, timer: null };
 29	  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
 30	  ws.onmessage = (e) => {
 31	    if (JSON.parse(e.data).t === 'joined' && !b.timer) b.timer = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x: BASE.x + ox, y: BASE.y + 5, z: BASE.z + oz, yaw: 0, bank: 0 })), 200);
 32	  };
 33	  b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
 34	  return b;
 35	}
 36	
 37	let srv, browser, page;
 38	const bots = [];
 39	try {
 40	  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
 41	  check('wrangler dev sẵn sàng', /Ready on/.test(log));
 42	  srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
 43	  browser = await launch();
 44	
 45	  // Mục 2 — không multi=: không mở WebSocket (cả ?explore=glider lẫn ?test thường)
 46	  for (const q of ['', '?explore=glider']) {
 47	    const P = await openApp(browser, srv.url + q);
 48	    let ws = 0; P.page.on('websocket', () => ws++);
 49	    await frames(P.page, 15);
 50	    const u = await P.page.evaluate(() => window.__app.multi.url());
 51	    check(`Không có multi= (${q || '?test'}): không có WebSocket nào được mở`, ws === 0 && u === '' && await P.page.evaluate(() => window.__app.multi.session) === null);
 52	    await P.page.close();
 53	  }
 54	
 55	  // Mục 3 — bước chọn slot và nhập tên (bắt đầu từ phòng trống; mọi bot/trang đóng trước Mục 1)
 56	  {
 57	    const URL3 = srv.url + '?chooser&multi=' + encodeURIComponent(`ws://${HOST}/sky`);
 58	    const lobbyBots = [bot('Linh', 90, 0), bot('<img src>', 110, 18), bot('Sakura', 130, -18)];
 59	    await sleep(2500);
 60	    const L = await openApp(browser, URL3);
 61	    await L.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
 62	    let ws3 = 0; L.page.on('websocket', () => ws3++);
 63	    check('Chưa bấm Dù lượn: không có phiên, không WebSocket', ws3 === 0 && await L.page.evaluate(() => window.__app.multi.session) === null);
 64	    const txt = (sel) => L.page.evaluate((s) => document.querySelector(s)?.innerText ?? null, sel);
 65	    const rows = () => L.page.evaluate(() => [...document.querySelectorAll('#exMpList .ex-mp-row span')].map((e) => e.textContent));
 66	    await L.page.click('#chooser [data-pick="glider"]');
 67	    await L.page.waitForFunction(() => /Còn 2 trên 5/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
 68	    const seats2 = await txt('#exMpSeats');
 69	    check(`Bấm Dù lượn: sảnh hiện "${seats2}" (Còn 2) và 3 tên bot`, /Còn 2 trên 5/.test(seats2 || '') && (await rows()).length === 3);
 70	    const sk = await L.page.evaluate(() => ({ lobbyVisible: !document.getElementById('exMpLobby').hidden, cardsHidden: document.querySelector('#chooser .ex-cards').hidden, heading: document.querySelector('#exMpLobby h2').innerText, filled: document.querySelectorAll('#exMpDots i.on').length, total: document.querySelectorAll('#exMpDots i').length, inert: !!document.getElementById('exLang').closest('[inert]') }));
 71	    check(`Sảnh thay thẻ trong cùng hộp thoại: tiêu đề "${sk.heading}", ${sk.filled}/${sk.total} chấm, ô ngôn ngữ còn dùng được`, sk.lobbyVisible && sk.cardsHidden && sk.heading === 'Bầu trời Đà Nẵng' && sk.filled === 3 && sk.total === 5 && !sk.inert);
 72	    lobbyBots.push(bot('مرحبا', 150, 0));
 73	    await L.page.waitForFunction(() => /Còn 1 trên 5/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
 74	    const r4 = await rows();
 75	    check(`Bot thứ tư vào: "Còn 1" không tải lại (${r4.join(' | ')})`, /Còn 1 trên 5/.test(await txt('#exMpSeats')) && r4.length === 4);
 76	    const html = await L.page.evaluate(() => ({ imgs: document.querySelectorAll('#chooser img').length, body: getComputedStyle(document.body).direction, root: document.documentElement.dir }));
 77	    check('Tên "<img src>" hiện nguyên chuỗi, không tạo phần tử img; tên RTL không đổi dir của body/trang', r4.includes('<img src>') && r4.includes('مرحبا') && html.imgs === 0 && html.body === 'ltr' && html.root === 'ltr');
 78	    // Tên 10 ký tự tắt nút; 'Trường' bật
 79	    await L.page.fill('#exMpNameIn', '1234567890');
 80	    const dis10 = await L.page.evaluate(() => document.getElementById('exMpFly').disabled);
 81	    await L.page.fill('#exMpNameIn', 'Trường');
 82	    const dis6 = await L.page.evaluate(() => document.getElementById('exMpFly').disabled);
 83	    await L.page.fill('#exMpNameIn', '');
 84	    const disEmpty = await L.page.evaluate(() => document.getElementById('exMpFly').disabled);
 85	    check(`Tên 10 ký tự: nút tắt (${dis10}); "Trường": bật (${!dis6}); rỗng: tắt (${disEmpty})`, dis10 && !dis6 && disEmpty);
 86	    // Đổi ngôn ngữ ngay ở bước riêng: dòng số chỗ dịch, tên giữ nguyên
 87	    await L.page.fill('#exMpNameIn', 'Trường');
 88	    await L.page.selectOption('#exLang', 'en');
 89	    const en = await L.page.evaluate(() => ({ seats: document.getElementById('exMpSeats').innerText, names: [...document.querySelectorAll('#exMpList .ex-mp-row span')].map((e) => e.textContent), btn: document.getElementById('exMpFly').innerText, v: document.getElementById('exMpNameIn').value }));
 90	    check(`Đổi sang en: "${en.seats}", nút "${en.btn}", tên bot và tên đã gõ giữ nguyên`, /1 of 5/.test(en.seats) && en.names.join('|') === r4.join('|') && en.v === 'Trường' && en.btn === 'Fly now');
 91	    await L.page.selectOption('#exLang', 'ar');
 92	    await frames(L.page, 3);
 93	    const ar = await L.page.evaluate(() => { const b = document.querySelector('#chooser .ex-box'), r = b.getBoundingClientRect(); return { dir: document.documentElement.dir, over: b.scrollWidth - b.clientWidth, inView: r.left >= 0 && r.right <= innerWidth }; });
 94	    check(`lang=ar: dir=${ar.dir}, hộp không tràn ngang (${ar.over} px) và nằm trong khung nhìn`, ar.dir === 'rtl' && ar.over <= 0 && ar.inView);
 95	    await L.page.selectOption('#exLang', 'vi');
 96	    // Tải lại: tên đã nhớ sẵn
 97	    await L.page.reload({ waitUntil: 'load' });
 98	    await L.page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
 99	    await L.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
100	    await L.page.click('#chooser [data-pick="glider"]');
101	    await L.page.waitForFunction(() => /Còn 1 trên 5/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
102	    const kept = await L.page.evaluate(() => ({ v: document.getElementById('exMpNameIn').value, off: document.getElementById('exMpFly').disabled, ls: localStorage.getItem('exMpName') }));
103	    check(`Tải lại: tên đã nhớ sẵn ("${kept.v}", localStorage "${kept.ls}"), nút Bay ngay bật`, kept.v === 'Trường' && kept.ls === 'Trường' && !kept.off);
104	    // Bay ngay -> vào trời với slot cuối
105	    await L.page.click('#exMpFly');
106	    await L.page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
107	    await frames(L.page, 5);
108	    const fl = await L.page.evaluate(() => ({ hidden: document.getElementById('chooser').hidden, slot: window.__app.multi.session.mySlot, roster: document.getElementById('exMpRoster').innerText }));
109	    check(`Bay ngay: hộp đóng, slot ${fl.slot}, roster đủ 5/5 có Trường và tên chứa thẻ HTML`, fl.hidden && fl.slot === 4 && /5\/5/.test(fl.roster) && fl.roster.includes('Trường') && fl.roster.includes('<img src>'));
110	    check('Lỗi console của trang sảnh = 0', L.errors.length === 0);
111	    if (L.errors.length) console.log(L.errors.join('\n'));
112	    await L.page.close();
113	    lobbyBots.forEach((b) => b.close());
114	
115	    // Máy chủ tắt: cổng không có gì
116	    const O = await openApp(browser, srv.url + '?chooser&multi=' + encodeURIComponent('ws://127.0.0.1:9/sky'));
117	    await O.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
118	    await O.page.click('#chooser [data-pick="glider"]');
119	    await O.page.waitForFunction(() => !document.getElementById('exMpOffline').hidden, null, { timeout: 30000 }).catch(() => {});
120	    const off = await O.page.evaluate(() => ({ msg: document.getElementById('exMpOffline').innerText, solo: !document.getElementById('exMpSolo').hidden, name: document.getElementById('exMpNameIn').offsetParent !== null, fly: document.getElementById('exMpFly').offsetParent !== null }));
121	    check(`Máy chủ tắt: hiện "${off.msg}" và nút Bay một mình, không đòi tên`, off.msg.length > 0 && off.solo && !off.name && !off.fly);
122	    await O.page.click('#exMpSolo');
123	    await O.page.waitForFunction(() => window.__app.explore.active(), null, { timeout: 60000 }).catch(() => {});
124	    check('Bấm Bay một mình: bay được, hộp đóng', await O.page.evaluate(() => window.__app.explore.active() && document.getElementById('chooser').hidden));
125	    check('Lỗi console của trang ngoại tuyến = 0', O.errors.length === 0);
126	    await O.page.close();
127	    await sleep(1500);
128	  }
129	
130	  // Mục 1
131	  const P = await openApp(browser, srv.url + '?multi=' + encodeURIComponent(`ws://${HOST}/sky`));
132	  page = P.page;
133	  check('multi.url() lấy từ ?multi=', await page.evaluate(() => window.__app.multi.url()) === `ws://${HOST}/sky`);
134	  await page.evaluate(() => window.__app.multi.fly('Tester'));
135	  await page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
136	  const mine = await page.evaluate(() => window.__app.multi.session.mySlot);
137	  check('vào phòng và bay với slot ' + mine, mine >= 0);
138	  // Ghim dù chính tại BASE sau mỗi lần animate (rAF đăng ký sau chạy sau)
139	  await page.evaluate((B) => {
140	    const s = window.__app.explore.state;
141	    const pin = () => { s.pos.set(B.x, B.y, B.z); s.yaw = 0; s.bank = 0; requestAnimationFrame(pin); };
142	    pin();
143	  }, BASE);
144	  // draw call: dựng hai lần, đo lần hai (LOD theo camera hiện tại)
145	  const calls = () => page.evaluate(() => { const { renderer, scene, camera } = window.__app; renderer.render(scene, camera); renderer.info.reset(); renderer.render(scene, camera); return renderer.info.render.calls; });
146	  await frames(page, 40);   // camera bám ổn định
147	  const c0 = await calls();
148	
149	  ['Ann', 'Binh', 'Chi', 'Dung'].forEach((n, i) => bots.push(bot(n, 90 + i * 20, (i - 1.5) * 18)));
150	  await page.waitForFunction(() => [0, 1, 2, 3, 4].filter(i => window.__app.multi.remotes.slotState(i)).length === 4, null, { timeout: 60000 });
151	  await frames(page, 20);
152	  const info = await page.evaluate(() => {
153	    const A = window.__app, R = A.multi.remotes, out = { slots: [], maps: [], labels: [], below: [], roster: null };
154	    for (let i = 0; i < 5; i++) {
155	      if (!R.slotState(i)) continue;
156	      out.slots.push(i);
157	      const g = R.group(i); const ids = []; g.traverse((o) => { if (o.isMesh && o.material && o.material.map) ids.push(o.material.map.uuid); });
158	      out.maps.push(ids.sort().join(','));
159	      const st = R.slotState(i), v = new A.THREE.Vector3(st.pos.x, st.pos.y, st.pos.z).project(A.camera);
160	      const py = (-v.y * 0.5 + 0.5) * innerHeight;
161	      const el = [...document.querySelectorAll('#exMpLabels .ex-mp-label')].find((e) => !e.hidden && e.textContent.startsWith(R.name(i) + ' '));
162	      out.labels.push(el ? el.textContent : null);
163	      out.below.push(el ? el.getBoundingClientRect().top - py : null);
164	    }
165	    out.roster = document.getElementById('exMpRoster').innerText;
166	    return out;
167	  });
168	  check('4 bot bay: exRemotes có 4 dù', info.slots.length === 4);
169	  check('4 màu khác nhau (4 bản đồ màu riêng: ' + info.maps.map((m) => m.length).join('/') + ')', new Set(info.maps).size === 4);
170	  check('nhãn hiện đúng tên (Ann, Binh, Chi, Dung) kèm khoảng cách', ['Ann', 'Binh', 'Chi', 'Dung'].every((n) => info.labels.some((l) => l && l.startsWith(n + ' · ') && /\d+ m|\d\.\d km/.test(l))));
171	  check('nhãn nằm dưới cánh: top của nhãn > điểm chiếu của dù (' + info.below.map((x) => x === null ? '-' : Math.round(x)).join(',') + ' px)', info.below.length === 4 && info.below.every((x) => x !== null && x > 0));
172	  check('roster: "Đang bay 5/5" và đủ 5 tên', /5\/5/.test(info.roster) && ['Tester', 'Ann', 'Binh', 'Chi', 'Dung'].every((n) => info.roster.includes(n)));
173	  const c4 = await calls();
174	  check(`Draw call chênh giữa 0 bot (${c0}) và 4 bot trong khung nhìn (${c4}) ≤ +4`, c4 - c0 <= 4);
175	
176	  bots.pop().close();
177	  await page.waitForFunction(() => [0, 1, 2, 3, 4].filter(i => window.__app.multi.remotes.slotState(i)).length === 3, null, { timeout: 30000 }).catch(() => {});
178	  const after = await page.evaluate(() => ({
179	    n: [0, 1, 2, 3, 4].filter(i => window.__app.multi.remotes.slotState(i)).length,
180	    roster: document.getElementById('exMpRoster').innerText, vis: [...document.querySelectorAll('#exMpLabels .ex-mp-label')].filter((e) => !e.hidden).length
181	  }));
182	  check(`Bot đóng kết nối: dù biến mất (còn ${after.n}), roster còn 4 người bay (3 bot + mình), nhãn còn ${after.vis}`, after.n === 3 && /4\/5/.test(after.roster) && !after.roster.includes('Dung') && after.vis === 3);
183	
184	  check('console không lỗi', P.errors.length === 0);
185	  if (P.errors.length) console.log(P.errors.join('\n'));
186	
187	  // Mục 4 (Task 7) — chế độ xem và lời mời vào chỗ trống. Dọn Mục 1 trước để phòng trống
188	  await page.close();
189	  bots.splice(0).forEach((b) => b.close());
190	  await sleep(2000);
191	  const URLW = srv.url + '?chooser&multi=' + encodeURIComponent(`ws://${HOST}/sky`);
192	  const live = [];
193	  const addBot = (n) => { const i = live.length; const b = bot(n, 90 + i * 20, (i - 2) * 15); b.name = n; live.push(b); return b; };
194	  const dropBot = (n) => { const i = live.findIndex((b) => b.name === n); if (i >= 0) live.splice(i, 1)[0].close(); };
195	  const watchedName = (pg) => pg.evaluate(() => { const A = window.__app, s = A.multi.session; return A.multi.remotes.name(s.watched); });
196	  const enterWatch = async (pg) => { await pg.waitForSelector('#chooser', { state: 'visible', timeout: 240000 }); await pg.click('#chooser [data-pick="glider"]'); await pg.waitForFunction(() => window.__app.explore.watching, null, { timeout: 30000 }).catch(() => {}); };
197	  ['W1', 'W2', 'W3', 'W4', 'W5'].forEach(addBot);
198	  await sleep(2500);
199	
200	  const W = await openApp(browser, URLW);
201	  await enterWatch(W.page);
202	  await W.page.waitForFunction(() => [0, 1, 2, 3, 4].filter((i) => window.__app.multi.remotes.slotState(i)).length === 5, null, { timeout: 60000 }).catch(() => {});
203	  await frames(W.page, 20);
204	  const w0 = await W.page.evaluate(() => { const A = window.__app, s = A.multi.session, el = document.getElementById('exMpWatch'); return { watching: A.explore.watching, active: A.explore.active(), mode: A.cam.mode, phase: s.phase, text: el.innerText, vis: el.getClientRects().length > 0, own: A.explore.glider, st: A.explore.state, body: document.body.classList.contains('explore'), chooser: document.getElementById('chooser').hidden, inviteHidden: document.getElementById('exMpInvite').getClientRects().length === 0 }; });
205	  const wn0 = await watchedName(W.page);
206	  check(`5 bot: Dù lượn vào thẳng chế độ xem, dòng "${w0.text}" có tên "${wn0}", không dù của mình, không có lời mời`, w0.watching && !w0.active && w0.mode === 'glider' && w0.phase === 'watching' && w0.vis && w0.text.includes(wn0) && /Đang xem/.test(w0.text) && w0.own === null && w0.st === null && w0.body && w0.chooser && w0.inviteHidden);
207	  const poses = () => W.page.evaluate(() => { const R = window.__app.multi.remotes, o = {}; for (let i = 0; i < 5; i++) { const st = R.slotState(i); if (st) o[i] = [st.pos.x, st.pos.y, st.pos.z]; } return o; });
208	  const before = await poses();
209	  for (const k of ['w', 'a', 's', 'd', 'ArrowUp', 'q']) await W.page.keyboard.press(k);
210	  await frames(W.page, 5);
211	  const after0 = await poses();
212	  const k0 = await W.page.evaluate(() => ({ keys: window.__app.keys.size, state: window.__app.explore.state, own: window.__app.explore.glider }));
213	  check('Xem: phím WASD/mũi tên/Q không đổi vị trí dù nào, keys rỗng, không có dù của mình', JSON.stringify(before) === JSON.stringify(after0) && k0.keys === 0 && k0.state === null && k0.own === null);
214	
215	  // Draw call: cùng một tư thế camera, 0 và 5 dù người khác
216	  const dc = await W.page.evaluate((B) => {
217	    const A = window.__app, R = A.multi.remotes, { renderer, scene, camera } = A;
218	    const gs = [0, 1, 2, 3, 4].map((i) => R.group(i)).filter(Boolean);
219	    camera.position.set(B.x - 60, B.y + 25, B.z + 10); camera.lookAt(B.x + 130, B.y, B.z); camera.updateMatrixWorld(true);
220	    const meas = () => { renderer.render(scene, camera); renderer.info.reset(); renderer.render(scene, camera); return renderer.info.render.calls; };
221	    const withB = meas(); gs.forEach((g) => { g.visible = false; }); const without = meas(); gs.forEach((g) => { g.visible = true; });
